// === Tab: helper ===
function getTangramShapes(S) {
	let shapes = [];

	shapes.push(new Polygon([[0, 0], [50, 50], [0, 100]], true));
	shapes.push(new Polygon([[100, 0], [50, 50], [0, 0]], true));
	shapes.push(new Polygon([[100, 0], [100, 50], [75, 25]], true));
	shapes.push(new Polygon([[100, 50], [100, 100], [50, 100]], true));
	shapes.push(new Polygon([[50, 100], [0, 100], [25, 75], [75, 75]], true));
	shapes.push(new Polygon([[25, 75], [75, 75], [50, 50]], true));
	shapes.push(new Polygon([[50, 50], [75, 25], [100, 50], [75, 75]], true));

	for (const sh of shapes) {
		sh.scale(S/100)
	}

	return shapes;
}

