/*
	Rotated Shapes #WCCChallenge "Tangram" //250916 
	https://openprocessing.org/sketch/2792171
	#generativeart #creativecoding #p5js

	Dear Raph and creative coding community,

	animation of palette based random colored rotating tangram tiles on a random point of a shape till no overlapping.
	Overlapping detection is not always correct, but doesnt matter :D

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

const { Point, Line, Polygon } = EpiShapeSvg; // external library https://cdn.jsdelivr.net/gh/epibyte/p5-epi-shapesvg@v0.0.19/dist/p5-epi-shapesvg.js
let shapesTangram;

const { EpiColors } = EpiColorsPckg;
let epiColors, FG, BG;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("animation of palette based random colored rotating tangram tiles on a random point of a shape till no overlapping");
	frameRate(60);

	init();
}

function init() {
	epiColors = new EpiColors();
	epiColors.getRandomPalette();
	FG = epiColors.FG;
	BG = epiColors.BG;

	const S = ~~(max(width, height) * 0.4);
	shapesTangram = getTangramShapes(S);
	// shuffle(shapesTangram, true);
	for (const sh of shapesTangram) sh.translate([(width-sh.bbox.width)/2, (height-sh.bbox.height)/2]);

	blendMode(BLEND);
	if (frameCount === 0) background(BG);
	background(BG);
	// blendMode(ADD);
	stroke(FG);
	strokeWeight(2);
	fill(BG);
	for (let i = 0; i < 99; i++) {
		stroke(epiColors.getRandomClr());
		circle(random(width), random(height), random(S/10, S/5));
	}
	stroke(BG);
	noFill();

	loop();
}

function draw() {
	// do n times for speed
	for (let speed = 0; speed < 10; speed++) {	
		for (const sh of shapesTangram) {
			// fill(color(random(100, 255), random(0, 200), random(200, 255)))
			fill(epiColors.getRandomClr()); // stroke(epiColors.getRandomClr());
			sh.drawShape();
			sh.rotate(0.075, sh.pts[0][~~random(sh.pts[0].length)]);
		}

		// look, if no overlapping
		let overlapping = false;
		for (let i = 0; i < shapesTangram.length - 1; i++) {	
			for (let j = i + 1; j < shapesTangram.length; j++) {
				if (shapesTangram[i].isOverlapping(shapesTangram[j])) overlapping = true;
			}
		}

		if (!overlapping) {
			// noLoop() removed for animation
			break;
		}
	} // repeat n times
}

function mousePressed() {
	if (mouseButton != RIGHT) init();
}
